package com.veltrix.study;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;
public final class StudyDatabase extends SQLiteOpenHelper{
 public StudyDatabase(Context c){super(c,"veltrix_study.db",null,2);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE topics(id TEXT PRIMARY KEY,week INTEGER,day INTEGER,subject TEXT,title TEXT,done INTEGER DEFAULT 0)");d.execSQL("CREATE TABLE notes(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,body TEXT,created_at INTEGER)");d.execSQL("CREATE TABLE scores(id INTEGER PRIMARY KEY AUTOINCREMENT,subject TEXT,score INTEGER,total INTEGER,created_at INTEGER)");d.execSQL("CREATE TABLE questions(id TEXT PRIMARY KEY,subject TEXT,year INTEGER,topic TEXT,prompt TEXT,a TEXT,b TEXT,c TEXT,d TEXT,answer TEXT,explanation TEXT,source_label TEXT,source_url TEXT,option_explanations TEXT,verified INTEGER DEFAULT 0)");d.execSQL("CREATE TABLE attempts(id INTEGER PRIMARY KEY AUTOINCREMENT,started_at INTEGER,submitted_at INTEGER,duration_seconds INTEGER DEFAULT 7200,total INTEGER DEFAULT 180,score INTEGER,source_year INTEGER,prepared_at INTEGER NOT NULL)");d.execSQL("CREATE TABLE attempt_answers(attempt_id INTEGER,question_id TEXT,selected TEXT,PRIMARY KEY(attempt_id,question_id))");}
 public void onUpgrade(SQLiteDatabase d,int old,int now){if(old<2){d.execSQL("ALTER TABLE questions ADD COLUMN topic TEXT NOT NULL DEFAULT ''");d.execSQL("ALTER TABLE questions ADD COLUMN source_label TEXT NOT NULL DEFAULT ''");d.execSQL("ALTER TABLE questions ADD COLUMN option_explanations TEXT NOT NULL DEFAULT '{}'");d.execSQL("ALTER TABLE attempts ADD COLUMN source_year INTEGER");d.execSQL("ALTER TABLE attempts ADD COLUMN prepared_at INTEGER NOT NULL DEFAULT 0");}}
 public void seed(String[][] p){SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{for(int w=0;w<p.length;w++)for(int i=0;i<p[w].length;i++){String[] a=p[w][i].split("\\|",2);ContentValues v=new ContentValues();v.put("id","w"+(w+1)+"t"+i);v.put("week",w+1);v.put("day",i/2);v.put("subject",a[0]);v.put("title",a[1]);d.insertWithOnConflict("topics",null,v,SQLiteDatabase.CONFLICT_IGNORE);}d.setTransactionSuccessful();}finally{d.endTransaction();}}
 public int importQuestionBank(Context context){SQLiteDatabase d=getWritableDatabase();try{java.io.InputStream in=context.getAssets().open("questions.json");java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);JSONObject root=new JSONObject(out.toString("UTF-8"));JSONArray arr=root.getJSONArray("questions");int imported=0;d.beginTransaction();try{for(int i=0;i<arr.length();i++){JSONObject q=arr.getJSONObject(i),o=q.getJSONObject("options"),oe=q.getJSONObject("optionExplanations");String answer=q.getString("answer");boolean valid=(q.getInt("year")==2025||q.getInt("year")==2026)&&!q.getString("prompt").trim().isEmpty()&&!q.getString("explanation").trim().isEmpty()&&q.getString("sourceUrl").startsWith("https://")&&"ABCD".contains(answer)&&"ABCD".chars().allMatch(ch->o.optString(String.valueOf((char)ch)).trim().length()>0&&oe.optString(String.valueOf((char)ch)).trim().length()>0);if(!valid)continue;ContentValues v=new ContentValues();v.put("id",String.valueOf(q.getInt("id")));v.put("subject",q.getString("subject"));v.put("year",q.getInt("year"));v.put("topic",q.optString("topic",""));v.put("prompt",q.getString("prompt"));v.put("a",o.getString("A"));v.put("b",o.getString("B"));v.put("c",o.getString("C"));v.put("d",o.getString("D"));v.put("answer",answer);v.put("explanation",q.getString("explanation"));v.put("source_label",q.getString("source"));v.put("source_url",q.getString("sourceUrl"));v.put("option_explanations",oe.toString());v.put("verified",1);if(d.insertWithOnConflict("questions",null,v,SQLiteDatabase.CONFLICT_REPLACE)!=-1)imported++;}d.setTransactionSuccessful();}finally{d.endTransaction();}return imported;}catch(Exception e){throw new IllegalStateException("Question bank import failed",e);}}
 public int count(String sql){try(Cursor c=getReadableDatabase().rawQuery(sql,null)){return c.moveToFirst()?c.getInt(0):0;}}
 public int done(){return count("SELECT COUNT(*) FROM topics WHERE done=1");}public int total(){return count("SELECT COUNT(*) FROM topics");}public int verifiedQuestions(){return count("SELECT COUNT(*) FROM questions WHERE verified=1");}
 public Map<String,Integer> questionCounts(){Map<String,Integer> m=new LinkedHashMap<>();for(String s:new String[]{"English","Mathematics","Economics","Geography"})try(Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM questions WHERE verified=1 AND subject=?",new String[]{s})){m.put(s,c.moveToFirst()?c.getInt(0):0);}return m;}
 public long prepareCbt(){Map<String,Integer> counts=questionCounts();String[] subjects={"English","Mathematics","Economics","Geography"};int[] sizes={60,40,40,40};for(int i=0;i<4;i++)if(counts.get(subjects[i])<sizes[i])return -1;SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{long id=d.insertOrThrow("attempts",null,values("total",180,"duration_seconds",7200,"prepared_at",System.currentTimeMillis()));Random r=new Random();for(int i=0;i<4;i++){ArrayList<String> ids=new ArrayList<>();try(Cursor c=d.rawQuery("SELECT id FROM questions WHERE verified=1 AND subject=? ORDER BY RANDOM() LIMIT "+sizes[i],new String[]{subjects[i]})){while(c.moveToNext())ids.add(c.getString(0));}if(ids.size()!=sizes[i])return -1;for(String q:ids){ContentValues v=new ContentValues();v.put("attempt_id",id);v.put("question_id",q);d.insertOrThrow("attempt_answers",null,v);}}d.setTransactionSuccessful();return id;}finally{d.endTransaction();}}
 private ContentValues values(String k1,int v1,String k2,int v2,String k3,long v3){ContentValues c=new ContentValues();c.put(k1,v1);c.put(k2,v2);c.put(k3,v3);return c;}
 public boolean beginCbt(long id){ContentValues v=new ContentValues();v.put("started_at",System.currentTimeMillis());return getWritableDatabase().update("attempts",v,"id=? AND started_at IS NULL AND submitted_at IS NULL",new String[]{String.valueOf(id)})==1;}
 public long activeAttempt(){try(Cursor c=getReadableDatabase().rawQuery("SELECT id FROM attempts WHERE submitted_at IS NULL ORDER BY id DESC LIMIT 1",null)){return c.moveToFirst()?c.getLong(0):-1;}}
 public long attemptStart(long id){try(Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(started_at,0) FROM attempts WHERE id=?",new String[]{String.valueOf(id)})){return c.moveToFirst()?c.getLong(0):0;}}
 public List<Question> attemptQuestions(long id){ArrayList<Question>a=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT q.id,q.subject,q.year,q.topic,q.prompt,q.a,q.b,q.c,q.d,q.answer,q.explanation,q.source_label,q.source_url,q.option_explanations,COALESCE(aa.selected,'') FROM attempt_answers aa JOIN questions q ON q.id=aa.question_id WHERE aa.attempt_id=? ORDER BY CASE q.subject WHEN 'English' THEN 1 WHEN 'Mathematics' THEN 2 WHEN 'Economics' THEN 3 ELSE 4 END, q.id",new String[]{String.valueOf(id)})){while(c.moveToNext())a.add(new Question(c));}return a;}
 public void saveAnswer(long attempt,String question,String choice){ContentValues v=new ContentValues();v.put("selected",choice);getWritableDatabase().update("attempt_answers",v,"attempt_id=? AND question_id=?",new String[]{String.valueOf(attempt),question});}
 public int submitCbt(long id){SQLiteDatabase d=getWritableDatabase();int score=0,total=0;try(Cursor c=d.rawQuery("SELECT q.answer,aa.selected FROM attempt_answers aa JOIN questions q ON q.id=aa.question_id WHERE aa.attempt_id=?",new String[]{String.valueOf(id)})){while(c.moveToNext()){total++;if(c.getString(0).equals(c.getString(1)))score++;}}ContentValues v=new ContentValues();v.put("submitted_at",System.currentTimeMillis());v.put("score",score);v.put("duration_seconds",Math.max(0,(int)((System.currentTimeMillis()-attemptStart(id))/1000)));d.update("attempts",v,"id=? AND started_at IS NOT NULL AND submitted_at IS NULL",new String[]{String.valueOf(id)});return score;}
 public List<Attempt> attempts(){ArrayList<Attempt>a=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,started_at,submitted_at,duration_seconds,total,score FROM attempts WHERE submitted_at IS NOT NULL ORDER BY submitted_at DESC",null)){while(c.moveToNext())a.add(new Attempt(c.getLong(0),c.getLong(1),c.getLong(2),c.getInt(3),c.getInt(4),c.getInt(5)));}return a;}
 public void tick(String id,boolean b){ContentValues v=new ContentValues();v.put("done",b?1:0);getWritableDatabase().update("topics",v,"id=?",new String[]{id});}
 public List<Topic> topics(int w){List<Topic>a=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,day,subject,title,done FROM topics WHERE week=? ORDER BY day,id",new String[]{""+w})){while(c.moveToNext())a.add(new Topic(c.getString(0),c.getInt(1),c.getString(2),c.getString(3),c.getInt(4)==1));}return a;}
 public void note(String t,String b){ContentValues v=new ContentValues();v.put("title",t);v.put("body",b);v.put("created_at",System.currentTimeMillis());getWritableDatabase().insert("notes",null,v);}
 public List<Note> notes(){List<Note>a=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT title,body,created_at FROM notes ORDER BY id DESC",null)){while(c.moveToNext())a.add(new Note(c.getString(0),c.getString(1),c.getLong(2)));}return a;}
 public void score(String s,int x,int t){ContentValues v=new ContentValues();v.put("subject",s);v.put("score",x);v.put("total",t);v.put("created_at",System.currentTimeMillis());getWritableDatabase().insert("scores",null,v);}
 public List<Score> scores(){List<Score>a=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT subject,score,total,created_at FROM scores ORDER BY id DESC",null)){while(c.moveToNext())a.add(new Score(c.getString(0),c.getInt(1),c.getInt(2),c.getLong(3)));}return a;}
 public static class Question{public String id,subject,topic,prompt,answer,explanation,source,sourceUrl,selected;public int year;public String[] options=new String[4];public JSONObject optionExplanations;Question(Cursor c){id=c.getString(0);subject=c.getString(1);year=c.getInt(2);topic=c.getString(3);prompt=c.getString(4);for(int i=0;i<4;i++)options[i]=c.getString(5+i);answer=c.getString(9);explanation=c.getString(10);source=c.getString(11);sourceUrl=c.getString(12);try{optionExplanations=new JSONObject(c.getString(13));}catch(Exception e){optionExplanations=new JSONObject();}selected=c.getString(14);}}
 public static class Attempt{public long id,start,submitted;public int seconds,total,score;Attempt(long i,long s,long u,int d,int t,int x){id=i;start=s;submitted=u;seconds=d;total=t;score=x;}}
 public static class Topic{public String id,subject,title;public int day;public boolean done;Topic(String i,int d,String s,String t,boolean b){id=i;day=d;subject=s;title=t;done=b;}}
 public static class Note{public String title,body;public long date;Note(String t,String b,long d){title=t;body=b;date=d;}}
 public static class Score{public String subject;public int score,total;public long date;Score(String s,int x,int t,long d){subject=s;score=x;total=t;date=d;}}
}